+    sex: 'MALE', height_mm: 1800, activity_level: 'MODERATE', height_unit: 'CM' };
+  const stub = {
+    $executeRaw: async () => { events.push('lock'); await onLock?.(); return 1; },
+    user: { findUnique: async () => user },
